import SwiftUI

/// Anatomical figure loaded from `anatomy.json` (generated by tools/anatomy.py from the
/// MIT-licensed react-native-body-highlighter artwork).
struct AnatomyFigure {
    struct Shape: Identifiable {
        let id: String
        let muscle: MuscleGroup
        let path: Path
    }

    struct View2D {
        let base: [Path]
        let muscles: [Shape]
    }

    let size: CGSize
    let front: View2D
    let back: View2D

    static let credit = "Anatomy artwork adapted from react-native-body-highlighter by ELABBASSI Hicham, MIT licence."

    private static let figures: [BodyModel: AnatomyFigure] = load()

    static func figure(_ model: BodyModel) -> AnatomyFigure {
        figures[model] ?? figures[.male] ?? AnatomyFigure(size: CGSize(width: 724, height: 1448), front: View2D(base: [], muscles: []), back: View2D(base: [], muscles: []))
    }

    func view(_ side: AnatomySide) -> View2D { side == .front ? front : back }

    /// Muscles that can be seen (and tapped) from a side.
    func muscles(on side: AnatomySide) -> [MuscleGroup] {
        var seen: [MuscleGroup] = []
        for shape in view(side).muscles where !seen.contains(shape.muscle) { seen.append(shape.muscle) }
        return MuscleGroup.allCases.filter { seen.contains($0) }
    }

    /// The side that shows more of the given muscles.
    func bestSide(for muscles: [MuscleGroup]) -> AnatomySide {
        guard !muscles.isEmpty else { return .front }
        let frontArea = area(of: muscles, side: .front)
        let backArea = area(of: muscles, side: .back)
        return frontArea >= backArea ? .front : .back
    }

    private func area(of muscles: [MuscleGroup], side: AnatomySide) -> CGFloat {
        view(side).muscles.filter { muscles.contains($0.muscle) }.reduce(0) { $0 + $1.path.boundingRect.width * $1.path.boundingRect.height }
    }

    /// Scales the figure (or a region of it) to fit a rect, centred.
    func transform(fitting rect: CGSize, region: CGRect? = nil) -> CGAffineTransform {
        let source = region ?? CGRect(origin: .zero, size: size)
        guard source.width > 0, source.height > 0, rect.width > 0, rect.height > 0 else { return .identity }
        let scale = min(rect.width / source.width, rect.height / source.height)
        let dx = (rect.width - source.width * scale) / 2 - source.minX * scale
        let dy = (rect.height - source.height * scale) / 2 - source.minY * scale
        return CGAffineTransform(a: scale, b: 0, c: 0, d: scale, tx: dx, ty: dy)
    }

    /// A padded square around some muscles, for close-up thumbnails.
    func focusRegion(for muscles: [MuscleGroup], side: AnatomySide) -> CGRect? {
        let rects = view(side).muscles.filter { muscles.contains($0.muscle) }.map { $0.path.boundingRect }
        guard var box = rects.first else { return nil }
        for rect in rects.dropFirst() { box = box.union(rect) }
        let edge = max(box.width, box.height, size.width * 0.42) * 1.25
        return CGRect(x: box.midX - edge / 2, y: box.midY - edge / 2, width: edge, height: edge)
    }

    private struct FileFigure: Decodable {
        struct Item: Decodable { let id: String; let muscle: String; let d: String }
        let width: Double
        let height: Double
        let front: [Item]
        let back: [Item]
        let frontBase: [String]
        let backBase: [String]
    }

    private struct File: Decodable {
        let male: FileFigure
        let female: FileFigure
    }

    private static func load() -> [BodyModel: AnatomyFigure] {
        guard let url = Bundle.main.url(forResource: "anatomy", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let file = try? JSONDecoder().decode(File.self, from: data) else { return [:] }
        func convert(_ figure: FileFigure) -> AnatomyFigure {
            func shapes(_ items: [FileFigure.Item]) -> [Shape] {
                items.compactMap { item in
                    guard let muscle = MuscleGroup(rawValue: item.muscle) else { return nil }
                    return Shape(id: item.id, muscle: muscle, path: SVGPath.parse(item.d))
                }
            }
            return AnatomyFigure(
                size: CGSize(width: figure.width, height: figure.height),
                front: View2D(base: figure.frontBase.map(SVGPath.parse), muscles: shapes(figure.front)),
                back: View2D(base: figure.backBase.map(SVGPath.parse), muscles: shapes(figure.back))
            )
        }
        return [.male: convert(file.male), .female: convert(file.female)]
    }
}

enum AnatomySide: String, CaseIterable, Identifiable {
    case front, back
    var id: String { rawValue }
    var displayName: String { self == .front ? "Front" : "Back" }
    var anatomicalName: String { self == .front ? "Anterior" : "Posterior" }
}

/// How strongly a muscle is shown.
enum MuscleEmphasis: Equatable {
    case none, secondary, primary
    /// 0…1 heat from recorded training.
    case heat(Double)
}

/// Minimal SVG path reader for the absolute M, L, H, V, C, Q and Z commands the generators write.
enum SVGPath {
    static func parse(_ string: String) -> Path {
        var path = Path()
        var tokens = tokenize(string)[...]
        var command: Character = "M"
        var current = CGPoint.zero

        func number() -> CGFloat? {
            guard let token = tokens.first, case .number(let value) = token else { return nil }
            tokens = tokens.dropFirst()
            return CGFloat(value)
        }
        func point() -> CGPoint? {
            guard let x = number(), let y = number() else { return nil }
            return CGPoint(x: x, y: y)
        }

        while let token = tokens.first {
            if case .command(let letter) = token {
                command = letter
                tokens = tokens.dropFirst()
                if letter == "Z" || letter == "z" {
                    path.closeSubpath()
                    continue
                }
            }
            switch command {
            case "M":
                guard let p = point() else { return path }
                path.move(to: p); current = p
                command = "L"
            case "L":
                guard let p = point() else { return path }
                path.addLine(to: p); current = p
            case "H":
                guard let x = number() else { return path }
                current = CGPoint(x: x, y: current.y); path.addLine(to: current)
            case "V":
                guard let y = number() else { return path }
                current = CGPoint(x: current.x, y: y); path.addLine(to: current)
            case "C":
                guard let c1 = point(), let c2 = point(), let p = point() else { return path }
                path.addCurve(to: p, control1: c1, control2: c2); current = p
            case "Q":
                guard let c = point(), let p = point() else { return path }
                path.addQuadCurve(to: p, control: c); current = p
            default:
                return path
            }
        }
        return path
    }

    private enum Token { case command(Character), number(Double) }

    private static func tokenize(_ string: String) -> [Token] {
        var tokens: [Token] = []
        var buffer = ""
        func flush() {
            if let value = Double(buffer) { tokens.append(.number(value)) }
            buffer = ""
        }
        for character in string {
            if character.isLetter && character != "e" && character != "E" {
                flush()
                tokens.append(.command(character))
            } else if character == "," || character == " " || character == "\n" || character == "\t" {
                flush()
            } else if character == "-" && !buffer.isEmpty && buffer.last != "e" && buffer.last != "E" {
                flush()
                buffer.append(character)
            } else {
                buffer.append(character)
            }
        }
        flush()
        return tokens
    }
}
